'use client';
import { useState } from 'react';
import Link from 'next/link';
import { Bookmark, NotebookPen, CalendarDays, ArrowUpRight, BookOpen, Scale, Library, FolderSearch, Printer, Check, ArrowRight, Clock3, GraduationCap } from 'lucide-react';
import { useWorkspace } from './WorkspaceProvider';
import { PageHeading, EmptyState, BookmarkButton } from './ui';
import { topicMap, topics } from '@/data';
import { lawMap } from '@/data/laws';
import { bookMap } from '@/data/books';
import { caseMap } from '@/data/cases';

function savedResource(id: string) {
  const [kind, key] = id.split(':');
  if (kind === 'topic' && topicMap[key]) return { title: topicMap[key].title, href: `/topics/${key}`, detail: `LESSON ${key}`, icon: BookOpen };
  if (kind === 'law' && lawMap[key]) return { title: lawMap[key].title, href: `/laws/${key}`, detail: 'LAW GUIDE', icon: Scale };
  if (kind === 'book' && bookMap[key]) return { title: bookMap[key].title, href: `/library/${key}`, detail: 'READING GUIDE', icon: Library };
  if (kind === 'case' && caseMap[key]) return { title: caseMap[key].title, href: `/cases/${key}`, detail: 'CASE FILE', icon: FolderSearch };
  return null;
}
export default function PersonalWorkspace({ initialTab = 'saved' }: { initialTab?: string }) {
  const [tab, setTab] = useState(initialTab); const { state, update, ready } = useWorkspace();
  const notes = Object.entries(state.notes).filter(([, text]) => text.trim()); const remaining = topics.filter(t => !state.completed.includes(t.id)); const perDay = Math.max(1, Math.floor(state.studyMinutes / 14)); const weeks = state.studyDays.length ? Math.ceil(remaining.length / (state.studyDays.length * perDay)) : 0;
  const today = new Date();
  return <div className="page-enter"><PageHeading eyebrow="MAKE ROOM FOR YOUR OWN CONNECTIONS" title="Your thinking lives here." description="Saved resources, personal notes, and a study rhythm that works for you."><Link href="/print?scope=notes" className="button button-secondary"><Printer size={16} />Print my notes</Link></PageHeading><div className="tabs personal-tabs" role="tablist" aria-label="Workspace sections">{[['saved', 'Saved resources', Bookmark], ['notes', 'My notes', NotebookPen], ['planner', 'Study planner', CalendarDays]].map(([id, label, Icon]) => { const TabIcon = Icon as typeof Bookmark; return <button key={id as string} role="tab" aria-selected={tab === id} className={tab === id ? 'active' : ''} onClick={() => setTab(id as string)}><TabIcon size={16} />{label as string}{id === 'saved' && <span className="tag tag-muted">{state.bookmarks.length}</span>}{id === 'notes' && <span className="tag tag-muted">{notes.length}</span>}</button>; })}</div>
    {tab === 'saved' && <div className="saved-resource-list">{state.bookmarks.map(id => { const item = savedResource(id); if (!item) return null; const Icon = item.icon; return <div className="saved-resource" key={id}><Link href={item.href}><span className="saved-resource-icon"><Icon size={20} /></span><div><small>{item.detail}</small><h3>{item.title}</h3></div><ArrowUpRight size={17} /></Link><BookmarkButton id={id} /></div>; })}{!state.bookmarks.length && <EmptyState title="Keep a good connection close." description="Use the bookmark button on any lesson, law guide, book, or case file. Your saved resources will appear here." />}</div>}
    {tab === 'notes' && <div>{notes.map(([key, text]) => <div className="personal-note" key={key}><div className="personal-note-header"><h3>{topicMap[key]?.title || caseMap[key.split(':')[1]]?.title || `Note ${key}`}</h3>{topicMap[key] ? <Link href={`/topics/${key}`}>Open lesson<ArrowUpRight size={12} className="inline ml-1" /></Link> : caseMap[key.split(':')[1]] ? <Link href={`/cases/${key.split(':')[1]}`}>Open case<ArrowUpRight size={12} className="inline ml-1" /></Link> : null}</div><textarea aria-label={`Notes for ${topicMap[key]?.title || key}`} value={text} maxLength={12000} disabled={!ready} onChange={e => update({ notes: { ...state.notes, [key]: e.target.value } })} /><small>{text.trim().split(/\s+/).length} words · Changes save automatically</small></div>)}{!notes.length && <EmptyState title="The best note is the one you understand." description="Open a lesson’s My notes tab or write a case reflection. Explain an idea, record a question, or connect a provision to an example." href={`/topics/${state.lastTopic}`} action="Write your first note" />}</div>}
    {tab === 'planner' && <div className="planner-layout"><div className="panel"><h2>A rhythm, not a race.</h2><p>Choose the days and session length you can realistically keep. We’ll map the remaining lessons into a suggested pace.</p><label className="field-label">Your study days</label><div className="weekday-picker">{['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((day, i) => <button key={i} className={state.studyDays.includes(i) ? 'active' : ''} aria-pressed={state.studyDays.includes(i)} aria-label={['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][i]} disabled={!ready} onClick={() => update({ studyDays: state.studyDays.includes(i) ? state.studyDays.filter(d => d !== i) : [...state.studyDays, i] })}>{day}<small>{state.studyDays.includes(i) ? <Check size={10} /> : '—'}</small></button>)}</div><label className="field-label">Minutes per study day</label><div className="planner-minutes">{[15, 30, 45, 60].map(m => <button key={m} className={state.studyMinutes === m ? 'active' : ''} disabled={!ready} onClick={() => update({ studyMinutes: m })}>{m} min</button>)}</div><div className="planner-notice"><Check size={12} className="inline mr-1" />Your plan saves automatically. This is a suggested pace, not a deadline.</div><h3 className="mt-8 mb-4">Your next seven days</h3><div className="planner-week">{Array.from({ length: 7 }, (_, i) => { const date = new Date(today); date.setDate(today.getDate() + i); const isStudy = state.studyDays.includes((date.getDay() + 6) % 7); const dayStart = i * perDay; const assigned = isStudy ? remaining.slice(dayStart, dayStart + perDay) : []; return <div key={i}><span>{date.toLocaleDateString('en', { weekday: 'short', day: 'numeric' })}</span><section>{assigned.length ? assigned.map(t => <Link key={t.id} href={`/topics/${t.id}`}>{t.id} · {t.title}<ArrowUpRight size={12} /></Link>) : <small>{isStudy ? 'All lessons completed' : 'A little breathing room'}</small>}</section></div>; })}</div></div><div className="planner-summary"><CalendarDays size={33} strokeWidth={1.5} /><h2>{remaining.length ? `${weeks} weeks of possibility.` : 'You’ve covered the course.'}</h2><p>You have <strong>{remaining.length} lessons</strong> left. At {state.studyMinutes} minutes on {state.studyDays.length} days a week, you can work through the course at your own pace.</p><p className="mt-4">Longer lessons may take more than one session. Make room for the labs, reflection, and revision.</p><Link className="button button-primary" href={`/topics/${remaining[0]?.id || '1.1'}`}>{remaining.length ? 'Take the next step' : 'Revisit the course'}<ArrowRight size={16} /></Link></div></div>}
  </div>;
}
